## Local calculator for the locked trajectory-classification model.
## The model bundle is generated by R/05_shap_analysis.R and is intentionally
## excluded from Git because it contains a development reference sample.
suppressPackageStartupMessages({library(shiny);library(ggplot2);library(dplyr)})

project_root <- normalizePath(Sys.getenv("SIC_PROJECT_ROOT",unset=".."),winslash="/",mustWork=FALSE)
bundle_file <- Sys.getenv("SIC_MODEL_BUNDLE",unset=file.path(project_root,"private","model_bundle.rds"))
if(!file.exists(bundle_file)) stop("Model bundle not found. Run the full pipeline or set SIC_MODEL_BUNDLE.")
bundle <- readRDS(bundle_file)

make_input <- function(v) {
  d <- bundle$defaults[[v]]
  if(d$type=="numeric") numericInput(paste0("x__",v),v,value=round(as.numeric(d$value),3),min=as.numeric(d$min),max=as.numeric(d$max))
  else selectInput(paste0("x__",v),v,choices=d$choices,selected=d$value)
}

ui <- fluidPage(
  tags$head(tags$style(HTML("body{font-family:Arial}.well{background:#f7f9fc}.risk{font-size:32px;font-weight:700;color:#b2182b}.note{color:#555;font-size:12px}"))),
  titlePanel("SIC trajectory classifier"),
  sidebarLayout(sidebarPanel(width=4,lapply(bundle$features,make_input),actionButton("predict","Calculate",class="btn-primary")),
    mainPanel(width=8,h3(textOutput("model_name")),div(class="risk",textOutput("risk")),textOutput("decision"),plotOutput("importance",height="420px"),
      div(class="note","Research-use only. This is a trajectory-class probability, not mortality risk or a treatment recommendation.")))
)

server <- function(input,output,session) {
  new_patient <- eventReactive(input$predict,{
    x <- lapply(bundle$features,function(v){d<-bundle$defaults[[v]];z<-input[[paste0("x__",v)]];if(d$type=="numeric")as.numeric(z) else factor(z,levels=d$choices)})
    names(x)<-bundle$features;as.data.frame(x,check.names=FALSE)
  },ignoreNULL=FALSE)
  prob <- reactive(as.numeric(predict(bundle$model,new_data=new_patient(),type="prob")$.pred_Class2))
  output$model_name <- renderText(paste("Locked model:",bundle$model_name))
  output$risk <- renderText(sprintf("Class 2 probability: %.1f%%",100*prob()))
  output$decision <- renderText(if(prob()>=bundle$threshold) sprintf("Above the frozen development threshold (%.3f).",bundle$threshold) else sprintf("Below the frozen development threshold (%.3f).",bundle$threshold))
  output$importance <- renderPlot({bundle$global_importance %>% slice_head(n=min(15,n())) %>% mutate(Feature=factor(Feature,levels=rev(Feature))) %>%
    ggplot(aes(MeanAbsSHAP,Feature))+geom_col(fill="#377EB8",width=.72)+labs(x="Mean absolute SHAP value",y=NULL)+theme_classic(base_size=12)})
}
shinyApp(ui,server)

